package com.sami.app.purchasing;
import com.sami.app.accounting.publicapi.PayablePostingPort; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.organization.service.*; import com.sami.app.purchasing.service.SupplierInvoiceService; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.jdbc.core.JdbcTemplate; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class SupplierInvoiceServiceBehaviorTest { @Mock JdbcTemplate jdbc; @Mock TenantContext tenants; @Mock OrganizationScopeService scope; @Mock FoundationAuditService audit; @Mock PayablePostingPort payable; SupplierInvoiceService service;
 @BeforeEach void setup(){service=new SupplierInvoiceService(jdbc,tenants,scope,audit,Optional.of(payable));when(tenants.requireTenantId()).thenReturn(7L);when(jdbc.queryForList(anyString(),eq(7L),eq(9L))).thenReturn(List.of(Map.of("id",1L)));}
 @Test void alreadyIssuedIsIdempotent(){Map<String,Object> row=new HashMap<>(Map.of("status","ISSUED","company_id",1L,"branch_id",2L));when(jdbc.queryForMap(anyString(),any(Object[].class))).thenReturn(row);assertEquals("ISSUED",service.issue(9L).get("status"));verifyNoInteractions(payable);}
 @Test void payableSuccessIssuesDraftAndAudits(){Map<String,Object> draft=new HashMap<>(Map.of("status","DRAFT","company_id",1L,"branch_id",2L,"supplier_id",3L,"total",BigDecimal.TEN));Map<String,Object> issued=new HashMap<>(draft);issued.put("status","ISSUED");issued.put("payable_posting_reference","PAYABLE-4");when(jdbc.queryForMap(anyString(),any(Object[].class))).thenReturn(draft,issued);when(payable.createPayable(any())).thenReturn("PAYABLE-4");assertEquals("ISSUED",service.issue(9L).get("status"));verify(payable).createPayable(argThat(c->c.supplierInvoiceId().equals(9L)&&c.amount().equals(BigDecimal.TEN)));verify(audit,atLeastOnce()).record(eq(7L),eq(1L),eq(2L),eq("SUPPLIER_INVOICE"),eq(9L),anyString(),any(),anyMap());}
 @Test void payableFailureLeavesDraft(){Map<String,Object> draft=new HashMap<>(Map.of("status","DRAFT","company_id",1L,"branch_id",2L,"supplier_id",3L,"total",BigDecimal.TEN));when(jdbc.queryForMap(anyString(),any(Object[].class))).thenReturn(draft);when(payable.createPayable(any())).thenThrow(new IllegalStateException("failed"));assertThrows(IllegalStateException.class,()->service.issue(9L));verify(payable).createPayable(any());}
}
